package com.yigongbao.backup.job;
/** 带 fencing token 的任务上下文，同时固化订单/文件级证据。 */
public final class JobExecutionContext {private final PersistentJobCoordinator c;private final JobEvidenceService evidence;private final long id;private final String owner;private final long token;private final long lease;private Long currentOrder;private Long currentSnapshot;private String currentFile;private String currentFileStep;public JobExecutionContext(PersistentJobCoordinator c,long id,String owner,long token,long lease){this(c,null,id,owner,token,lease);}public JobExecutionContext(PersistentJobCoordinator c,JobEvidenceService evidence,long id,String owner,long token,long lease){this.c=c;this.evidence=evidence;this.id=id;this.owner=owner;this.token=token;this.lease=lease;}public void heartbeat(){c.heartbeat(id,owner,token,lease);}public void safePoint(String step,long progress){c.safePoint(id,owner,token,step,progress);c.heartbeat(id,owner,token,lease);}public void result(String json){c.storeResult(id,owner,token,json);}public void orderStarted(Long source,Long snapshot){currentOrder=source;currentSnapshot=snapshot;if(evidence!=null)evidence.order(id,source,snapshot,"RUNNING",null);}public void orderSucceeded(){if(evidence!=null&&currentOrder!=null)evidence.order(id,currentOrder,currentSnapshot,"SUCCEEDED",null);currentOrder=null;currentSnapshot=null;}public void orderFailed(Throwable failure){if(evidence!=null&&currentOrder!=null)evidence.order(id,currentOrder,currentSnapshot,"FAILED",failure);}public void fileStarted(Long source,String identity,String step,long total){currentFile=identity;currentFileStep=step;if(evidence!=null)evidence.file(id,source,identity,step,"RUNNING",0,total,null);}public void fileSucceeded(Long source,long bytes){if(currentFile!=null)fileSucceeded(source,currentFile,currentFileStep,bytes);}public void fileSucceeded(Long source,String identity,String step,long bytes){if(evidence!=null&&identity!=null)evidence.file(id,source,identity,step,"SUCCEEDED",bytes,bytes,null);if(identity!=null&&identity.equals(currentFile)){currentFile=null;currentFileStep=null;}}public void fileFailed(Long source,Throwable failure){if(currentFile!=null)fileFailed(source,currentFile,currentFileStep,failure);}public void fileFailed(Long source,String identity,String step,Throwable failure){if(evidence!=null&&identity!=null)evidence.file(id,source,identity,step,"FAILED",0,0,failure);if(identity!=null&&identity.equals(currentFile)){currentFile=null;currentFileStep=null;}}public void failure(Throwable failure){fileFailed(currentOrder,failure);orderFailed(failure);}public long jobId(){return id;}public long fencingToken(){return token;}}
